#define WPE_LOG_MODULE "assets"
#include "assets/font.h"

/* wpe__builtin_font_png: the bytes of assets/fonts/small.png, generated by CMake at configure time. */
#include "assets/builtin_font_data.h"

WPE_Result wpe_font_create_builtin(WPE_BitmapFont** out_font) {
    if (!out_font) return WPE_RESULT_ERROR_NULL_ARG;
    return wpe_font_load_memory(wpe__builtin_font_png, sizeof wpe__builtin_font_png, "built-in font",
                                out_font);
}
